// Pagamentos alterados desde a última sync (date_last_updated pega
// também liberação e estorno de pagamento antigo). Devolve só os campos
// que mp_sincronizar_pagamentos usa — o token fica fora da saída.
const { empresa_id, access_token, buscar_desde } = $json;
const desde = new Date(buscar_desde).toISOString();
const pagamentos = [];
try {
  for (let offset = 0; offset < 5000; offset += 100) {
    const r = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://api.mercadopago.com/v1/payments/search',
      qs: { sort: 'date_last_updated', criteria: 'asc', range: 'date_last_updated', begin_date: desde, end_date: 'NOW', limit: 100, offset },
      headers: { Authorization: `Bearer ${access_token}` },
      json: true,
    });
    for (const p of r.results || []) {
      pagamentos.push({
        id: String(p.id),
        status: p.status,
        external_reference: p.external_reference,
        transaction_amount: p.transaction_amount,
        net_received_amount: p.transaction_details?.net_received_amount ?? null,
        transaction_amount_refunded: p.transaction_amount_refunded ?? 0,
        date_approved: p.date_approved,
        date_last_updated: p.date_last_updated,
        money_release_date: p.money_release_date,
        money_release_status: p.money_release_status,
        payment_type_id: p.payment_type_id,
        payment_method_id: p.payment_method_id,
        installments: p.installments,
      });
    }
    const total = r.paging?.total ?? 0;
    if (!r.results?.length || offset + 100 >= total) break;
  }
  return { json: { empresa_id, pagamentos, erro: null } };
} catch (e) {
  const status = e.httpCode || e.response?.status || '';
  return { json: { empresa_id, pagamentos: [], erro: `Mercado Pago ${status}: ${e.message}`.slice(0, 400) } };
}

// Saldo do Mercado Pago (API de saldo = 403): relatório de liberações.
// Pede um relatório novo (últimos 3 dias) se o mais recente tiver mais de 5h
// e baixa o mais recente pronto; mp_gravar_relatorio_liberacoes ignora
// arquivo já processado. Saldo = BALANCE_AMOUNT da última linha com data.
const { empresa_id, access_token } = $json;
const base = 'https://api.mercadopago.com/v1/account/release_report';
const headers = { Authorization: `Bearer ${access_token}` };
try {
  const lista = await this.helpers.httpRequest({ method: 'GET', url: `${base}/list`, headers, json: true });
  const prontos = (lista || []).filter((r) => r.status === 'enabled' && r.file_name)
    .sort((a, b) => new Date(b.date_created) - new Date(a.date_created));
  const recente = (lista || []).sort((a, b) => new Date(b.date_created) - new Date(a.date_created))[0];
  if (!recente || Date.now() - new Date(recente.date_created).getTime() > 5 * 3600e3) {
    const agora = new Date();
    await this.helpers.httpRequest({
      method: 'POST', url: base, headers, json: true,
      body: { begin_date: new Date(agora - 3 * 864e5).toISOString().slice(0, 19) + 'Z', end_date: agora.toISOString().slice(0, 19) + 'Z' },
    });
  }
  const r = prontos[0];
  if (!r) return { json: { empresa_id, pular: true } };
  const csv = await this.helpers.httpRequest({ method: 'GET', url: `${base}/${r.file_name}`, headers, json: false });
  const linhas = String(csv).split(/\r?\n/).filter(Boolean);
  const cab = linhas[0].split(';');
  const col = (n) => cab.indexOf(n);
  const [iData, iId, iDesc, iDeb, iSaldo] = ['DATE', 'SOURCE_ID', 'DESCRIPTION', 'NET_DEBIT_AMOUNT', 'BALANCE_AMOUNT'].map(col);
  const dados = linhas.slice(1).map((l) => l.split(';')).filter((c) => c[iData]);
  if (!dados.length || iSaldo < 0) return { json: { empresa_id, pular: true } };
  const saldo = Number(dados[dados.length - 1][iSaldo]);
  const saques = dados.filter((c) => (c[iDesc] || '').toLowerCase() === 'payout')
    .map((c) => ({ id: c[iId], data: c[iData], valor: Number(c[iDeb]) }));
  return { json: { empresa_id, arquivo: r.file_name, saldo, fim: r.end_date, saques, pular: false } };
} catch (e) {
  return { json: { empresa_id, pular: true, erro: `Relatório MP: ${e.message}`.slice(0, 300) } };
}
